/**
 * Opt-in message content for the GenAI trace formats. Nothing here is
 * recorded unless a content variable is set.
 */
export const CAPTURE_MESSAGE_CONTENT_ENV = "OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT";
/**
 * `true` / `span_only` / `span_and_event` put content on spans. `false`,
 * `no_content`, and `event_only` do not: Agent SDK emits no GenAI events.
 */
export function captureMessageContentFromEnv(env) {
    const raw = env[CAPTURE_MESSAGE_CONTENT_ENV]?.trim().toLowerCase();
    switch (raw) {
        case undefined:
        case "":
        case "false":
        case "0":
        case "no_content":
        case "event_only":
            return { capture: false, warning: undefined };
        case "true":
        case "1":
        case "span_only":
        case "span_and_event":
            return { capture: true, warning: undefined };
        default:
            return {
                capture: false,
                warning: `${CAPTURE_MESSAGE_CONTENT_ENV}='${env[CAPTURE_MESSAGE_CONTENT_ENV]}' is not true, false, span_only, span_and_event, event_only, or no_content; not capturing content`,
            };
    }
}
/** `gen_ai.input.messages`: one user message per prompt in the turn. */
export function inputMessages(texts) {
    return JSON.stringify(texts.map((content) => ({ role: "user", parts: [{ type: "text", content }] })));
}
/** `gen_ai.output.messages`: the turn's final assistant message. */
export function outputMessages(content, finishReason) {
    return JSON.stringify([
        { role: "assistant", parts: [{ type: "text", content }], finish_reason: finishReason },
    ]);
}
